SELECT business_id, name, address, city, state, postal_code, stars, review_count, categories
FROM business
WHERE city = 'Tampa' AND categories LIKE '%Dry Cleaning%';

SELECT review_id, business_id, stars, date, text
FROM review
WHERE review_id IN ('rid1','rid2',...);

SELECT review_id, business_id, stars, date, text
FROM review
WHERE review_id IN (?,?,...);

SELECT business_id, name, address, stars, review_count
FROM business
WHERE business_id IN (?,?,...);

SELECT business_id, name, stars, review_count, categories, address
FROM business
WHERE city = 'Santa Barbara'
  AND (
    categories LIKE '%Italian%' OR categories LIKE '%Pasta%' OR categories LIKE '%Restaurants%'
  );

